<?php
/* Maintainer tool: needs PHP >= 8.0 (tokenizer) and GNU gperf 3.3. Normal
 * extension builds use the checked-in redis_readonly_commands.h. */
declare(strict_types=1);

/* Collect commands tagged `@redis-readonly [COMMAND]` in RedisCluster method
 * docblocks. COMMAND defaults to the uppercased method name. */
function redisReadonlyCommands(string $source): array {
    $tokens = PhpToken::tokenize($source);
    $skip = [T_WHITESPACE, T_COMMENT, T_ABSTRACT, T_FINAL, T_PUBLIC,
             T_PROTECTED, T_PRIVATE, T_STATIC];
    $commands = [];
    $inClass = false;

    for ($i = 0, $count = count($tokens); $i < $count; $i++) {
        $token = $tokens[$i];
        if (!$inClass) {
            if ($token->id !== T_CLASS) continue;
            while (++$i < $count && $tokens[$i]->id === T_WHITESPACE) {}
            if ($i === $count || $tokens[$i]->text !== 'RedisCluster') continue;
            while (++$i < $count && $tokens[$i]->text !== '{') {}
            if ($i === $count) throw new RuntimeException('Unterminated RedisCluster declaration');
            $inClass = true;
            continue;
        }
        if ($token->text === '}') break;
        if ($token->id !== T_DOC_COMMENT) continue;

        preg_match_all('/@redis-(\S+)(.*?)(?=\*\/|$)/m', $token->text, $tags, PREG_SET_ORDER);
        if (!$tags) continue;
        if (count($tags) > 1 || $tags[0][1] !== 'readonly') {
            throw new RuntimeException("Invalid or duplicate @redis- tag: {$tags[0][0]}");
        }
        $command = trim($tags[0][2]);
        if ($command !== '' && !preg_match('/^[A-Za-z][A-Za-z0-9_.]*$/D', $command)) {
            throw new RuntimeException("Invalid @redis-readonly command: $command");
        }

        while (++$i < $count && in_array($tokens[$i]->id, $skip, true)) {}
        if ($i === $count || $tokens[$i]->id !== T_FUNCTION) {
            throw new RuntimeException('@redis-readonly must annotate a RedisCluster method');
        }
        while (++$i < $count && $tokens[$i]->id === T_WHITESPACE) {}
        if ($i === $count || $tokens[$i]->id !== T_STRING) {
            throw new RuntimeException('Expected a RedisCluster method name');
        }
        $commands[strtoupper($command ?: $tokens[$i]->text)] = true;
    }
    if (!$commands) throw new RuntimeException('No readonly RedisCluster commands found');
    $commands = array_keys($commands);
    sort($commands, SORT_STRING);
    return $commands;
}

function redisReadonlyHeader(array $commands): string {
    $input = "%{\n#include <stddef.h>\n" .
        "static const char *redis_readonly_command(const char *str, size_t len);\n%}\n%%\n";
    $input .= implode("\n", $commands) . "\n%%\n";
    $args = ['gperf', '--ignore-case', '--compare-lengths', '--readonly-tables',
             '--enum', '--includes', '--language=ANSI-C',
             '--lookup-function-name=redis_readonly_command',
             '--hash-function-name=redis_readonly_hash',
             '--word-array-name=redis_readonly_words'];
    $process = proc_open($args, [['pipe', 'r'], ['pipe', 'w'], ['pipe', 'w']], $pipes);
    if (!is_resource($process)) throw new RuntimeException('Unable to start gperf');
    fwrite($pipes[0], $input);
    fclose($pipes[0]);
    $output = stream_get_contents($pipes[1]);
    $error = stream_get_contents($pipes[2]);
    fclose($pipes[1]);
    fclose($pipes[2]);
    if (proc_close($process) !== 0) throw new RuntimeException("gperf failed: $error");
    return "/* Generated by .github/scripts/generate-readonly-commands.php from redis_cluster.stub.php. */\n" .
        "#ifndef REDIS_READONLY_COMMANDS_H\n#define REDIS_READONLY_COMMANDS_H\n\n" . $output . "\n#endif\n";
}

if (realpath($_SERVER['SCRIPT_FILENAME']) === __FILE__) {
    try {
        if ($argc > 2 || ($argc === 2 && $argv[1] !== '--check')) {
            throw new RuntimeException('Usage: php .github/scripts/generate-readonly-commands.php [--check]');
        }
        $root = dirname(__DIR__, 2);
        $source = file_get_contents("$root/redis_cluster.stub.php");
        if ($source === false) throw new RuntimeException('Unable to read cluster stub');
        $output = redisReadonlyHeader(redisReadonlyCommands($source));
        $path = "$root/redis_readonly_commands.h";
        if ($argc === 2) {
            if (!is_file($path) || file_get_contents($path) !== $output) {
                throw new RuntimeException('Readonly LUT is stale; run .github/scripts/generate-readonly-commands.php with gperf 3.3');
            }
            echo "Readonly LUT is current\n";
        } elseif (file_put_contents($path, $output) === false) {
            throw new RuntimeException("Unable to write $path");
        }
    } catch (Throwable $error) {
        fwrite(STDERR, $error->getMessage() . "\n");
        exit(1);
    }
}
